        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 0 24px 24px;
      }

      .meta h1 {
        margin: 0;
        font-size: clamp(1.2rem, 2vw, 1.55rem);
      }

      .meta p {
        margin: 4px 0 0;
        color: var(--muted);
      }

      .danger-button,
      .secondary-button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.15rem;
        cursor: pointer;
        transition: transform 150ms ease, box-shadow 150ms ease, background 150ms ease;
      }

      .danger-button {
        color: #fff;
        background: linear-gradient(180deg, var(--danger), var(--danger-strong));
        box-shadow: 0 10px 24px rgba(255, 61, 87, 0.28);
      }

      .secondary-button {
        color: var(--text);
        background: rgba(255, 255, 255, 0.06);
        border: 1px solid var(--border);
      }

      .danger-button:hover,
      .secondary-button:hover {
        transform: translateY(-1px);
      }

      .danger-button:focus-visible,
      .secondary-button:focus-visible,
      .trigger:focus-visible {
        outline: 3px solid rgba(79, 140, 255, 0.55);
        outline-offset: 2px;
      }

      .trigger {
        min-width: 120px;
      }

      .backdrop {
        position: fixed;
        inset: 0;
        display: grid;
        place-items: center;
        padding: 24px;
        background: rgba(5, 8, 12, 0.72);
        backdrop-filter: blur(10px);
      }

      .backdrop[hidden] {
        display: none;
      }

      .dialog {
        width: min(520px, 100%);
        background: linear-gradient(180deg, rgba(25, 33, 46, 0.98), rgba(16, 22, 31, 0.98));
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .dialog__header {
        padding: 24px 24px 0;
      }

      .dialog__eyebrow {
        margin: 0 0 10px;
        color: #ff8f9b;
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      .dialog__title {
        margin: 0;
        font-size: 1.45rem;
      }

      .dialog__body {
        padding: 14px 24px 0;
        color: var(--muted);
      }

      .dialog__footer {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        padding: 24px;
      }

      .visually-hidden {
        position: absolute;
        width: 1px;
        height: 1px;
        margin: -1px;
        padding: 0;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        border: 0;
        white-space: nowrap;
      }

